package dashboard

const controlPage = `
<section class="panel full" id="proposals" aria-labelledby="proposals-heading"><div class="panel-head"><h2 id="proposals-heading">Rule-change proposals</h2><span class="hint">Review through the normal org flow</span></div><p class="error" id="proposals-error"></p><div class="scroll" id="proposals-content"><p class="empty">Loading recorded proposals…</p></div></section>
<section class="panel full" id="tools" aria-labelledby="tools-heading"><div class="panel-head"><h2 id="tools-heading">Tool submissions</h2><label>Employee<select id="tools-employee"><option value="">All employees</option></select></label></div><p class="error" id="tools-error"></p><div class="scroll" id="tools-content"><p class="empty">Loading submitted tools…</p></div></section>
`

const controlScript = `
let refusalData=null,toolData=[];
const refusalHead=byId('refusals').querySelector('.panel-head');
[['refusal-employee','Employee'],['refusal-level','Level']].forEach(([id,title])=>{const label=node('label',title),select=node('select');select.id=id;label.append(select);refusalHead.append(label);select.addEventListener('change',()=>{if(refusalData)renderRefusalGroups(refusalData);});});
const refusalNote=node('p','Effect labels describe recorded refusal text. Unresolved effects stay opaque.','muted');
const refusalTrend=node('div');refusalTrend.id='refusal-trend';
byId('refusals-content').before(refusalNote,refusalTrend);
const reportForm=node('form',undefined,'body'),reportSelect=node('select'),reportNote=node('textarea'),reportButton=node('button','File proposal'),reportStatus=node('p',undefined,'send-status');
reportForm.id='refusal-report';reportSelect.id='report-group';reportSelect.required=true;reportNote.id='report-note';reportNote.rows=3;reportNote.maxLength=4000;reportNote.required=true;reportButton.type='submit';reportStatus.setAttribute('role','status');
const groupLabel=node('label','Refusal group'),noteLabel=node('label','Why this may be a false block');groupLabel.append(reportSelect);noteLabel.append(reportNote);
reportForm.append(node('h3','Report a likely false block'),node('p','Records a proposal for human review. Policy changes follow the org’s normal review and tool-post flow.','muted'),groupLabel,noteLabel,reportButton,reportStatus);byId('refusals').append(reportForm);
function renderRefusalGroups(data){refusalData=data;selectOptions('refusal-employee',data.groups.map(r=>r.employee),'All employees');selectOptions('refusal-level',data.groups.filter(r=>r.level!==null).map(r=>String(r.level)),'All levels');const rows=data.groups.filter(r=>(!byId('refusal-employee').value||r.employee===byId('refusal-employee').value)&&(!byId('refusal-level').value||String(r.level)===byId('refusal-level').value));setData(byId('refusals-count'),nf(data.count));const hours=new Map();data.hours.filter(r=>(!byId('refusal-employee').value||r.employee===byId('refusal-employee').value)&&(!byId('refusal-level').value||String(r.level)===byId('refusal-level').value)).forEach(r=>hours.set(r.hour,(hours.get(r.hour)||0)+r.count));byId('refusal-trend').replaceChildren(node('p','Recorded refusals per hour','muted'),sparkline([...hours].sort(([a],[b])=>a.localeCompare(b)).map(([time,value])=>({time,value})),'Refusals per hour'));
 const previous=reportSelect.value,initial=node('option','Choose an effect and rule group');initial.value='';reportSelect.replaceChildren(initial);const choices=new Map();data.groups.forEach(r=>{const key=JSON.stringify({rule:r.rule_id,effect:r.effect});const group=choices.get(key)||{label:r.effect+' / '+r.rule_id,count:0};group.count+=r.count;choices.set(key,group);});choices.forEach((group,key)=>{const option=node('option',tr('{effect} / {rule} · {count} refusals across employees',{effect:JSON.parse(key).effect,rule:JSON.parse(key).rule,count:nf(group.count)}));option.value=key;reportSelect.append(option);});reportSelect.value=previous;
 table('refusals-content',['Effect / rule','Employee / level','Count','First / last seen','Screened examples','Records'],rows.map(r=>({cells:[r.effect+' / '+r.rule_id,pairCell(r.employee,levelText(r.level)),r.count,stamp(r.first_seen)+' / '+stamp(r.last_seen),r.examples.map(e=>e.example).join('\n'),sourceLink(r.source)],classes:['','lane','','nowrap','summary','']})),'No recorded refusal groups match these filters.');}
function renderProposals(data){table('proposals-content',['Time / ID','Rule','Count','Employees','Human note','Records'],data.map(r=>({cells:[stamp(r.time)+' / '+r.id,r.rule_id,r.count,(r.lanes||[]).join(', '),r.note,sourceLink(r.source)],classes:['nowrap','','','lane','summary','']})),'No rule-change proposals have been recorded.');}
function renderTools(data){toolData=data;selectOptions('tools-employee',data.map(r=>r.instance||r.lane),'All employees');const selected=byId('tools-employee').value;table('tools-content',['Employee','Path / SHA-256','Purpose','Screened preview','Recorded'],data.filter(r=>!selected||(r.instance||r.lane)===selected).map(r=>({cells:[r.instance||r.lane,r.path+'\n'+r.sha256,r.purpose,r.preview,stamp(r.time)],classes:['lane','summary','summary','summary','nowrap']})),'No submitted tools match this employee.');}
byId('tools-employee').addEventListener('change',()=>renderTools(toolData));
function renderJudgeControl(data){setData(byId('judge-count'),nf(data.rows.length));let summary=byId('judge-share');if(!summary){summary=node('p',undefined,'muted');summary.id='judge-share';byId('judge-content').before(summary);}setText(summary,tr('Judged share: {share} · {judged} / {total} explicit guard/refusal decisions. Low confidence: 0.25 < probability < 0.75.',{share:data.judged_share===null?tr('no data'):pct(data.judged_share),judged:nf(data.decisions_judged),total:nf(data.recorded_decisions)}));table('judge-content',['Time','Employee / question','Typed answer / probability','Rule / allow or refuse','Latency (ms)','Outcome / confidence'],data.rows.map(r=>({late:r.low_confidence===true,cells:[stamp(r.time),value(r.lane)+' / '+r.question,pairCell(r.answer.type,measured(r.answer.probability)),value(r.rule_id)+' / '+value(r.result),measuredCell(r.latency_ms),node('span',tr('{outcome}{confidence}',{outcome:stateText(r.outcome),confidence:r.low_confidence===true?tr(' · Low confidence'):''}))],classes:['nowrap','summary','','','','']})),'No judge decisions have been recorded.');}
reportForm.addEventListener('submit',async event=>{event.preventDefault();reportButton.disabled=true;reportStatus.textContent='Recording proposal…';try{const group=JSON.parse(reportSelect.value),response=await fetch('/api/refusals/report',{method:'POST',headers:authHeaders({'Content-Type':'application/json'}),credentials:'omit',body:JSON.stringify({...group,note:reportNote.value})});const data=await response.json();if(!response.ok)throw new Error(serverError(data.error,'Report refused.'));reportStatus.textContent='Proposal recorded. Policy unchanged.';reportNote.value='';await fetchPanel('proposals','/api/proposals',renderProposals,true);await fetchPanel('events',eventPath,renderEvents,true);}catch(error){setText(reportStatus,serverError(error.message,'Report refused.'));}finally{reportButton.disabled=false;}});
panels.forEach(panel=>{if(panel[0]==='refusals'){panel[1]='/api/refusals?view=groups';panel[2]=renderRefusalGroups;}if(panel[0]==='judge'){panel[1]='/api/judge?view=control';panel[2]=renderJudgeControl;}});
panels.push(['proposals','/api/proposals',renderProposals],['tools','/api/tools',renderTools]);
`
